struct DeepDelegateCreationSyntax final
{
    std::vector<std::unique_ptr<nativesharp::ast::AstNode>> nodes;
    std::vector<nativesharp::frontend::MethodDelegateBinding> delegates;
    std::vector<nativesharp::frontend::MethodLambdaBinding> lambdas;
    const nativesharp::ast::AstNode* root = nullptr;
};

nativesharp::frontend::MethodLambdaBinding makeDelegateReceiverLambda(
    const nativesharp::ast::AstNode* syntax,
    bool validCapture = true)
{
    nativesharp::frontend::MethodLambdaCapture capture;
    capture.name = "captured";
    capture.typeKey = "builtin:int";
    capture.sourceKind =
        nativesharp::frontend::MethodLambdaCaptureSourceKind::OriginalLocal;
    if (validCapture) capture.sourceOrdinal = 41U;
    capture.mode = nativesharp::language::CaptureMode::MutableReference;
    capture.clearMovedSource = true;

    nativesharp::frontend::MethodLambdaBinding binding;
    binding.syntax = syntax;
    binding.lambdaOrdinal = 73U;
    binding.delegateTypeKey = "delegate:Deep::Receiver";
    binding.generatedName = "Deep.Receiver.lambda$73";
    binding.captures.push_back(std::move(capture));
    return binding;
}

DeepDelegateCreationSyntax makeDeepDelegateCreationSyntax(
    std::size_t depth,
    std::size_t selectedMemberOrdinal)
{
    DeepDelegateCreationSyntax fixture;
    fixture.nodes.reserve(depth + 1U);
    fixture.delegates.reserve(depth);
    fixture.lambdas.reserve(1U);
    fixture.nodes.push_back(std::make_unique<nativesharp::ast::AstNode>(
        nativesharp::ast::AstNodeKind::LambdaExpression,
        nativesharp::SourceRange{}));
    fixture.lambdas.push_back(makeDelegateReceiverLambda(fixture.nodes.back().get()));
    const nativesharp::ast::AstNode* receiver = fixture.nodes.back().get();
    for (std::size_t index = 0; index < depth; ++index)
    {
        fixture.nodes.push_back(std::make_unique<nativesharp::ast::AstNode>(
            nativesharp::ast::AstNodeKind::IdentifierExpression,
            nativesharp::SourceRange{}));
        nativesharp::frontend::MethodDelegateBinding binding;
        binding.syntax = fixture.nodes.back().get();
        binding.delegateTypeKey = "delegate:Deep::Receiver";
        binding.selectedMemberOrdinal = selectedMemberOrdinal;
        binding.receiverSyntax = receiver;
        binding.receiverTypeKey = "builtin:object";
        fixture.delegates.push_back(std::move(binding));
        receiver = fixture.nodes.back().get();
    }
    fixture.root = receiver;
    return fixture;
}

bool deepDelegateCreationMatches(
    const ProjectOopHirNode* node,
    std::size_t expectedDepth,
    std::size_t selectedMemberOrdinal)
{
    using HirKind = nativesharp::frontend::ProjectOopHirNodeKind;
    std::size_t observedDepth = 0U;
    while (node != nullptr && node->kind == HirKind::DelegateCreate)
    {
        if (node->memberOrdinal != selectedMemberOrdinal ||
            node->typeKey != "delegate:Deep::Receiver" ||
            node->elementTypeKey != "delegate:Deep::Receiver" ||
            node->children.size() != 1U || node->booleanValue ||
            node->interfaceDispatch ||
            node->ownership != nativesharp::sema::OwnershipKind::Borrowed)
        {
            return false;
        }
        ++observedDepth;
        node = node->children.front().get();
    }
    return observedDepth == expectedDepth && node != nullptr &&
        node->kind == HirKind::LambdaCreate &&
        node->typeKey == "delegate:Deep::Receiver" &&
        node->elementTypeKey == "delegate:Deep::Receiver" &&
        node->stringValue == "Deep.Receiver.lambda$73" &&
        node->integerValue == 73U && node->children.size() == 1U &&
        node->children.front()->kind == HirKind::CaptureCellReference &&
        node->children.front()->localOrdinal == 41U &&
        node->children.front()->captureMode ==
            nativesharp::language::CaptureMode::MutableReference &&
        node->children.front()->booleanValue;
}

std::unique_ptr<ProjectOopHirNode> lowerDelegateCreationFixture(
    const ProjectCompilation& compilation,
    const nativesharp::ast::AstNode* root,
    const std::vector<nativesharp::frontend::MethodDelegateBinding>& delegates,
    const std::vector<nativesharp::frontend::MethodLambdaBinding>& lambdas,
    std::string& error)
{
    ProjectOopHirModel model;
    return nativesharp::frontend::ProjectOopHirModelTestAccess::
        lowerDelegateCreationExpression(
            model,
            *compilation.nameLookup(),
            *compilation.memberModel(),
            root,
            delegates,
            lambdas,
            error);
}

void testDelegateCreationLeafContracts(
    TestContext& tests,
    const ProjectCompilation& compilation,
    const UserBinaryOperatorTarget& target)
{
    using HirKind = nativesharp::frontend::ProjectOopHirNodeKind;
    const auto makeSyntax = []()
    {
        return std::make_unique<nativesharp::ast::AstNode>(
            nativesharp::ast::AstNodeKind::IdentifierExpression,
            nativesharp::SourceRange{});
    };

    {
        auto syntax = makeSyntax();
        nativesharp::frontend::MethodDelegateBinding binding;
        binding.syntax = syntax.get();
        binding.delegateTypeKey = "delegate:Deep::Static";
        binding.selectedMemberOrdinal = target.operatorOrdinal;
        binding.staticTarget = true;
        std::string error;
        auto lowered = lowerDelegateCreationFixture(
            compilation, syntax.get(), {binding}, {}, error);
        tests.expect(lowered != nullptr && error.empty() &&
                lowered->kind == HirKind::DelegateCreate && lowered->children.empty(),
            "static delegate creation remains a receiver-free leaf");
    }
    for (const bool fromLocal : {true, false})
    {
        auto syntax = makeSyntax();
        auto receiver = makeSyntax();
        nativesharp::frontend::MethodDelegateBinding binding;
        binding.syntax = syntax.get();
        binding.delegateTypeKey = "delegate:Deep::Owned";
        binding.selectedMemberOrdinal = target.operatorOrdinal;
        binding.receiverSyntax = receiver.get();
        binding.receiverTypeKey = target.nodeType;
        binding.ownsReceiver = true;
        if (fromLocal) binding.receiverSourceLocalOrdinal = 11U;
        else binding.receiverSourceParameterOrdinal = 13U;
        std::string error;
        auto lowered = lowerDelegateCreationFixture(
            compilation, syntax.get(), {binding}, {}, error);
        const ProjectOopHirNode* moved = lowered != nullptr &&
                lowered->children.size() == 1U
            ? lowered->children.front().get() : nullptr;
        tests.expect(lowered != nullptr && error.empty() &&
                lowered->ownership == nativesharp::sema::OwnershipKind::Owned &&
                moved != nullptr && moved->kind == HirKind::MoveValue &&
                moved->booleanValue &&
                moved->localOrdinal == (fromLocal
                    ? std::optional<std::size_t>{11U} : std::nullopt) &&
                moved->parameterOrdinal == (fromLocal
                    ? std::nullopt : std::optional<std::size_t>{13U}),
            fromLocal
                ? "owned-local delegate receiver remains one direct MoveValue"
                : "owned-parameter delegate receiver remains one direct MoveValue");
    }
}

void testDelegateCreationReceiverContracts(
    TestContext& tests,
    const ProjectCompilation& compilation,
    const UserBinaryOperatorTarget& target)
{
    using HirKind = nativesharp::frontend::ProjectOopHirNodeKind;
    auto receiver = std::make_unique<nativesharp::ast::AstNode>(
        nativesharp::ast::AstNodeKind::LambdaExpression,
        nativesharp::SourceRange{});
    auto syntax = std::make_unique<nativesharp::ast::AstNode>(
        nativesharp::ast::AstNodeKind::IdentifierExpression,
        nativesharp::SourceRange{});
    nativesharp::frontend::MethodLambdaBinding lambda =
        makeDelegateReceiverLambda(receiver.get());
    nativesharp::frontend::MethodDelegateBinding binding;
    binding.syntax = syntax.get();
    binding.delegateTypeKey = "delegate:Deep::Interface";
    binding.selectedMemberOrdinal = target.operatorOrdinal;
    binding.receiverSyntax = receiver.get();
    binding.receiverTypeKey = target.nodeType;
    binding.receiverTypeOrdinal = 19U;
    binding.virtualDispatch = true;
    binding.interfaceDispatch = true;
    std::string error;
    auto lowered = lowerDelegateCreationFixture(
        compilation, syntax.get(), {binding}, {lambda}, error);
    const ProjectOopHirNode* temporary = lowered != nullptr &&
            lowered->children.size() == 1U
        ? lowered->children.front().get() : nullptr;
    tests.expect(lowered != nullptr && error.empty() &&
            lowered->kind == HirKind::DelegateCreate && lowered->booleanValue &&
            lowered->interfaceDispatch && lowered->targetTypeOrdinal == 19U &&
            temporary != nullptr && temporary->kind == HirKind::TemporaryAddress &&
            temporary->elementTypeKey == target.nodeType &&
            temporary->children.size() == 1U &&
            temporary->children.front()->kind == HirKind::LambdaCreate,
        "delegate frame preserves dispatch and materializes one struct receiver temporary");

    binding.selectedMemberOrdinal.reset();
    error.clear();
    auto invalid = lowerDelegateCreationFixture(
        compilation, syntax.get(), {binding}, {lambda}, error);
    tests.expect(invalid == nullptr &&
            error == "Stage 42 delegate creation has no selected callable",
        "invalid delegate target preserves the exact Stage 42 diagnostic");

    lambda = makeDelegateReceiverLambda(receiver.get(), false);
    error.clear();
    auto missingCapture = lowerDelegateCreationFixture(
        compilation, receiver.get(), {}, {lambda}, error);
    tests.expect(missingCapture == nullptr &&
            error == "Stage 43 lambda capture source is unavailable",
        "missing lambda capture preserves the exact Stage 43 diagnostic");
}

void testDeepDelegateLambdaReceiverLowering(
    TestContext& tests,
    const std::filesystem::path& root)
{
    constexpr std::size_t nestingDepth = 32768U;
    ProjectCompilation compilation;
    UserBinaryOperatorTarget target;
    std::string error;
    const bool prepared = prepareUserBinaryOperatorFixture(
        root, compilation, target, error);
    tests.expect(prepared,
        "the delegate receiver fixture provides a valid selected callable (" + error + ")");
    if (!prepared) return;

    DeepDelegateCreationSyntax fixture = makeDeepDelegateCreationSyntax(
        nestingDepth, target.operatorOrdinal);
    auto lowered = lowerDelegateCreationFixture(
        compilation,
        fixture.root,
        fixture.delegates,
        fixture.lambdas,
        error);
    tests.expect(lowered != nullptr && error.empty(),
        "a 32768-level delegate receiver chain lowers without stack recursion (" +
            error + ")");
    tests.expect(deepDelegateCreationMatches(
            lowered.get(), nestingDepth, target.operatorOrdinal),
        "delegate frames preserve every receiver and the terminal lambda captures");
    destroyHirTreeIteratively(lowered);

    testDelegateCreationLeafContracts(tests, compilation, target);
    testDelegateCreationReceiverContracts(tests, compilation, target);
}

struct DelegateInvokeTarget final
{
    nativesharp::frontend::MethodDelegateBinding binding;
};

bool prepareDelegateInvokeFixture(
    const std::filesystem::path& root,
    ProjectCompilation& compilation,
    DelegateInvokeTarget& output,
    std::string& error)
{
    const auto directory = root / "DeepDelegateInvoke";
    writeProject(directory, "DeepDelegateInvoke");
    writeFile(directory / "Main.ns", R"ns(
namespace Deep {
public delegate int Add(int first, int second = 5);
public class Host {
    public static int Run(Add add) { return add(1); }
}
}
)ns");
    if (!compilation.compileProjectOopHir(directory / "DeepDelegateInvoke.nsproj", error) ||
        compilation.methodBodyModel() == nullptr)
    {
        return false;
    }
    for (const auto& binding : compilation.methodBodyModel()->delegateBindings())
    {
        if (binding.kind == nativesharp::frontend::MethodDelegateOperationKind::Invoke &&
            binding.directLambdaName.empty() && !binding.resultTypeKey.empty() &&
            !binding.delegateTypeKey.empty())
        {
            output.binding = binding;
            return true;
        }
    }
    error = "delegate-invoke fixture produced no ordinary invoke binding";
    return false;
}

enum class DelegateInvokeFixtureMode : std::uint8_t
{
    Ordinary,
    DirectEnvironment,
    DirectStatic,
};

struct DelegateInvokeSyntax final
{
    std::vector<std::unique_ptr<nativesharp::ast::AstNode>> nodes;
    std::vector<nativesharp::frontend::MethodDelegateBinding> bindings;
    const nativesharp::ast::AstNode* root = nullptr;
};

nativesharp::ast::AstNode* appendDelegateInvokeSyntax(
    DelegateInvokeSyntax& fixture,
    nativesharp::ast::AstNodeKind kind)
{
    fixture.nodes.push_back(std::make_unique<nativesharp::ast::AstNode>(
        kind, nativesharp::SourceRange{}));
    return fixture.nodes.back().get();
}

void selectDelegateInvokeMode(
    nativesharp::frontend::MethodDelegateBinding& binding,
    DelegateInvokeFixtureMode mode)
{
    binding.directLambdaName.clear();
    binding.directLambdaUsesEnvironment = false;
    if (mode == DelegateInvokeFixtureMode::DirectEnvironment)
    {
        binding.directLambdaName = "Deep.Add.lambda$environment";
        binding.directLambdaUsesEnvironment = true;
    }
    else if (mode == DelegateInvokeFixtureMode::DirectStatic)
    {
        binding.directLambdaName = "Deep.Add.lambda$static";
    }
}

DelegateInvokeSyntax makeSingleDelegateInvokeSyntax(
    const nativesharp::frontend::MethodDelegateBinding& semanticBinding,
    DelegateInvokeFixtureMode mode,
    std::size_t argumentCount)
{
    DelegateInvokeSyntax fixture;
    fixture.nodes.reserve(argumentCount + 2U);
    fixture.bindings.reserve(1U);
    auto* callee = appendDelegateInvokeSyntax(
        fixture,
        mode == DelegateInvokeFixtureMode::DirectStatic
            ? nativesharp::ast::AstNodeKind::CallExpression
            : nativesharp::ast::AstNodeKind::NullLiteralExpression);
    auto* call = appendDelegateInvokeSyntax(
        fixture, nativesharp::ast::AstNodeKind::CallExpression);
    call->setFirst(callee);
    for (std::size_t index = 0; index < argumentCount; ++index)
    {
        auto* argument = appendDelegateInvokeSyntax(
            fixture, nativesharp::ast::AstNodeKind::IntegerLiteralExpression);
        argument->setIntegerValue(index + 1U);
        call->addChild(argument);
    }
    fixture.bindings.push_back(semanticBinding);
    auto& binding = fixture.bindings.back();
    binding.kind = nativesharp::frontend::MethodDelegateOperationKind::Invoke;
    binding.syntax = call;
    binding.argumentConversions.clear();
    binding.selectedDefaultArguments.clear();
    binding.selectedDefaultArgumentTypeKeys.clear();
    selectDelegateInvokeMode(binding, mode);
    fixture.root = call;
    return fixture;
}

DelegateInvokeSyntax makeDeepDelegateInvokeSyntax(
    std::size_t depth,
    const nativesharp::frontend::MethodDelegateBinding& semanticBinding)
{
    DelegateInvokeSyntax fixture;
    fixture.nodes.reserve(depth * 2U + 1U);
    fixture.bindings.reserve(depth);
    auto* current = appendDelegateInvokeSyntax(
        fixture, nativesharp::ast::AstNodeKind::NullLiteralExpression);
    for (std::size_t index = 0; index < depth; ++index)
    {
        const auto mode = static_cast<DelegateInvokeFixtureMode>(index % 3U);
        nativesharp::ast::AstNode* callee = current;
        if (mode == DelegateInvokeFixtureMode::DirectStatic)
        {
            // An unbound call would fail immediately if direct static invocation evaluated it.
            callee = appendDelegateInvokeSyntax(
                fixture, nativesharp::ast::AstNodeKind::CallExpression);
        }
        auto* call = appendDelegateInvokeSyntax(
            fixture, nativesharp::ast::AstNodeKind::CallExpression);
        call->setFirst(callee);
        if (mode == DelegateInvokeFixtureMode::DirectStatic) call->addChild(current);

        fixture.bindings.push_back(semanticBinding);
        auto& binding = fixture.bindings.back();
        binding.kind = nativesharp::frontend::MethodDelegateOperationKind::Invoke;
        binding.syntax = call;
        binding.argumentConversions.clear();
        binding.selectedDefaultArguments.clear();
        binding.selectedDefaultArgumentTypeKeys.clear();
        selectDelegateInvokeMode(binding, mode);
        if (mode == DelegateInvokeFixtureMode::DirectStatic)
        {
            nativesharp::frontend::ProjectImplicitConversion identity;
            identity.kind = nativesharp::frontend::ProjectConversionKind::Identity;
            identity.sourceTypeKey = semanticBinding.resultTypeKey;
            identity.targetTypeKey = semanticBinding.resultTypeKey;
            binding.argumentConversions.push_back(std::move(identity));
        }
        current = call;
    }
    fixture.root = current;
    return fixture;
}

std::unique_ptr<ProjectOopHirNode> lowerDelegateInvokeFixture(
    DelegateInvokeSyntax& fixture,
    const nativesharp::frontend::MethodExpressionTypeBinding& expressionType,
    bool addressContext,
    std::string& error)
{
    ProjectOopHirModel model;
    return nativesharp::frontend::ProjectOopHirModelTestAccess::
        lowerDelegateInvokeExpression(
            model,
            fixture.root,
            fixture.nodes,
            fixture.bindings,
            expressionType,
            addressContext,
            error);
}

bool deepDelegateInvokeMatches(
    const ProjectOopHirNode* node,
    std::size_t expectedDepth,
    const DelegateInvokeTarget& target)
{
    using HirKind = nativesharp::frontend::ProjectOopHirNodeKind;
    std::size_t observedDepth = 0U;
    while (node != nullptr && node->kind == HirKind::DelegateInvoke)
    {
        const std::size_t sourceIndex = expectedDepth - observedDepth - 1U;
        const auto mode = static_cast<DelegateInvokeFixtureMode>(sourceIndex % 3U);
        const bool ordinary = mode == DelegateInvokeFixtureMode::Ordinary;
        const bool environment = mode == DelegateInvokeFixtureMode::DirectEnvironment;
        const bool directStatic = mode == DelegateInvokeFixtureMode::DirectStatic;
        const std::string expectedName = ordinary
            ? std::string{}
            : environment ? "Deep.Add.lambda$environment" : "Deep.Add.lambda$static";
        if (node->typeKey != target.binding.resultTypeKey ||
            node->elementTypeKey != target.binding.delegateTypeKey ||
            node->stringValue != expectedName || node->booleanValue != environment ||
            node->argumentCount != (directStatic ? 1U : 0U) ||
            node->children.size() != 1U ||
            node->argumentTypeKeys.size() != (directStatic ? 1U : 0U) ||
            (directStatic &&
                node->argumentTypeKeys.front() != target.binding.resultTypeKey))
        {
            return false;
        }
        ++observedDepth;
        node = node->children.front().get();
    }
    return observedDepth == expectedDepth && node != nullptr &&
        node->kind == HirKind::NullConstant;
}

void testDelegateInvokeContracts(
    TestContext& tests,
    const DelegateInvokeTarget& target,
    const nativesharp::frontend::MethodExpressionTypeBinding& expressionType)
{
    using HirKind = nativesharp::frontend::ProjectOopHirNodeKind;
    std::string error;
    for (const auto mode : {DelegateInvokeFixtureMode::Ordinary,
             DelegateInvokeFixtureMode::DirectEnvironment,
             DelegateInvokeFixtureMode::DirectStatic})
    {
        auto fixture = makeSingleDelegateInvokeSyntax(target.binding, mode, 0U);
        auto lowered = lowerDelegateInvokeFixture(fixture, expressionType, false, error);
        const bool lowersCallee = mode != DelegateInvokeFixtureMode::DirectStatic;
        tests.expect(lowered != nullptr && error.empty() &&
                lowered->kind == HirKind::DelegateInvoke && lowered->argumentCount == 0U &&
                lowered->children.size() == (lowersCallee ? 1U : 0U) &&
                lowered->stringValue == (mode == DelegateInvokeFixtureMode::Ordinary
                    ? std::string{}
                    : mode == DelegateInvokeFixtureMode::DirectEnvironment
                        ? "Deep.Add.lambda$environment" : "Deep.Add.lambda$static") &&
                lowered->booleanValue ==
                    (mode == DelegateInvokeFixtureMode::DirectEnvironment),
            mode == DelegateInvokeFixtureMode::Ordinary
                ? "ordinary delegate invoke evaluates its zero-argument callee exactly once"
                : mode == DelegateInvokeFixtureMode::DirectEnvironment
                    ? "direct environment lambda invoke retains exactly one callee child"
                    : "direct static lambda invoke omits its deliberately unbound callee");
        destroyHirTreeIteratively(lowered);
        error.clear();
    }

    auto arguments = makeSingleDelegateInvokeSyntax(
        target.binding, DelegateInvokeFixtureMode::DirectStatic, 3U);
    nativesharp::frontend::ProjectImplicitConversion identity;
    identity.kind = nativesharp::frontend::ProjectConversionKind::Identity;
    identity.sourceTypeKey = target.binding.resultTypeKey;
    identity.targetTypeKey = target.binding.resultTypeKey;
    nativesharp::frontend::ProjectImplicitConversion numeric;
    numeric.kind = nativesharp::frontend::ProjectConversionKind::Numeric;
    numeric.sourceTypeKey = "builtin:byte";
    numeric.targetTypeKey = "builtin:long";
    arguments.bindings.front().argumentConversions = {identity, numeric};
    auto argumentNode = lowerDelegateInvokeFixture(arguments, expressionType, false, error);
    tests.expect(argumentNode != nullptr && error.empty() &&
            argumentNode->argumentCount == 3U && argumentNode->children.size() == 3U &&
            argumentNode->children[0]->kind == HirKind::IntegerConstant &&
            argumentNode->children[1]->kind == HirKind::Conversion &&
            argumentNode->children[2]->kind == HirKind::IntegerConstant &&
            argumentNode->argumentTypeKeys ==
                std::vector<std::string>{target.binding.resultTypeKey, "builtin:long"},
        "delegate invoke preserves source-order arguments and a short conversion vector");
    destroyHirTreeIteratively(argumentNode);

    auto defaults = makeSingleDelegateInvokeSyntax(
        target.binding, DelegateInvokeFixtureMode::Ordinary, 0U);
    auto* literal = appendDelegateInvokeSyntax(
        defaults, nativesharp::ast::AstNodeKind::IntegerLiteralExpression);
    literal->setIntegerValue(7U);
    auto* unaryLeaf = appendDelegateInvokeSyntax(
        defaults, nativesharp::ast::AstNodeKind::IntegerLiteralExpression);
    unaryLeaf->setIntegerValue(8U);
    auto* unary = appendDelegateInvokeSyntax(
        defaults, nativesharp::ast::AstNodeKind::UnaryExpression);
    unary->setTokenKind(nativesharp::lexer::TokenKind::Minus);
    unary->setFirst(unaryLeaf);
    auto* string = appendDelegateInvokeSyntax(
        defaults, nativesharp::ast::AstNodeKind::StringLiteralExpression);
    string->setText("default");
    auto* emptyType = appendDelegateInvokeSyntax(
        defaults, nativesharp::ast::AstNodeKind::IntegerLiteralExpression);
    emptyType->setIntegerValue(9U);
    defaults.bindings.front().selectedDefaultArguments =
        {literal, unary, string, emptyType};
    defaults.bindings.front().selectedDefaultArgumentTypeKeys =
        {"builtin:int", "builtin:int", "builtin:string"};
    error.clear();
    auto defaultNode = lowerDelegateInvokeFixture(defaults, expressionType, false, error);
    const auto* stringDefault = defaultNode != nullptr && defaultNode->children.size() == 5U
        ? defaultNode->children[3].get() : nullptr;
    tests.expect(defaultNode != nullptr && error.empty() &&
            defaultNode->argumentCount == 4U && defaultNode->children.size() == 5U &&
            defaultNode->children[1]->kind == HirKind::IntegerConstant &&
            defaultNode->children[2]->kind == HirKind::Unary &&
            stringDefault != nullptr && stringDefault->kind == HirKind::Conversion &&
            stringDefault->children.size() == 1U &&
            stringDefault->children.front()->kind == HirKind::StringLiteral &&
            defaultNode->children[4]->kind == HirKind::IntegerConstant &&
            defaultNode->argumentTypeKeys.size() == 4U &&
            defaultNode->argumentTypeKeys.back().empty(),
        "delegate invoke appends literal, unary, string, and empty-type defaults in order");
    destroyHirTreeIteratively(defaultNode);

    auto missingDefault = makeSingleDelegateInvokeSyntax(
        target.binding, DelegateInvokeFixtureMode::Ordinary, 0U);
    missingDefault.bindings.front().selectedDefaultArguments = {nullptr};
    missingDefault.bindings.front().selectedDefaultArgumentTypeKeys = {"builtin:int"};
    error.clear();
    auto rejectedDefault = lowerDelegateInvokeFixture(
        missingDefault, expressionType, false, error);
    tests.expect(rejectedDefault == nullptr &&
            error == "NSC-LIMIT-020 selected optional parameter has no default expression",
        "delegate invoke preserves the exact invalid-default diagnostic");

    auto address = makeSingleDelegateInvokeSyntax(
        target.binding, DelegateInvokeFixtureMode::Ordinary, 1U);
    error.clear();
    auto rejectedAddress = lowerDelegateInvokeFixture(address, expressionType, true, error);
    tests.expect(rejectedAddress == nullptr &&
            error == "Stage 42 delegate invocation is not addressable",
        "delegate invoke preserves the exact address-context diagnostic");
}

void testDeepDelegateLambdaInvokeLowering(
    TestContext& tests,
    const std::filesystem::path& root)
{
    constexpr std::size_t nestingDepth = 32768U;
    ProjectCompilation compilation;
    DelegateInvokeTarget target;
    std::string error;
    const bool prepared = prepareDelegateInvokeFixture(root, compilation, target, error);
    tests.expect(prepared,
        "the delegate-invoke fixture builds a real ordinary invoke binding (" + error + ")");
    if (!prepared) return;

    nativesharp::frontend::MethodExpressionTypeBinding expressionType;
    expressionType.typeKey = target.binding.resultTypeKey;
    DelegateInvokeSyntax fixture = makeDeepDelegateInvokeSyntax(
        nestingDepth, target.binding);
    auto lowered = lowerDelegateInvokeFixture(fixture, expressionType, false, error);
    tests.expect(lowered != nullptr && error.empty(),
        "a 32768-level ordinary/environment/static delegate-invoke chain lowers without "
        "process-stack recursion (" + error + ")");
    tests.expect(deepDelegateInvokeMatches(lowered.get(), nestingDepth, target),
        "delegate-invoke frames preserve callee policy, argument counts, order, and metadata");
    destroyHirTreeIteratively(lowered);

    testDelegateInvokeContracts(tests, target, expressionType);
}

struct AssertionCoreSyntax final
{
    std::vector<std::unique_ptr<nativesharp::ast::AstNode>> nodes;
    std::vector<nativesharp::frontend::MethodCoreBinding> cores;
    const nativesharp::ast::AstNode* root = nullptr;
};

nativesharp::ast::AstNode* appendAssertionCoreSyntax(
    AssertionCoreSyntax& fixture,
    nativesharp::ast::AstNodeKind kind)
{
    fixture.nodes.push_back(std::make_unique<nativesharp::ast::AstNode>(
        kind, nativesharp::SourceRange{}));
    return fixture.nodes.back().get();
}

nativesharp::frontend::MethodCoreBinding makeAssertionCoreBinding(
    const nativesharp::ast::AstNode* syntax,
    nativesharp::frontend::MethodCoreOperationKind kind)
{
    nativesharp::frontend::MethodCoreBinding binding;
    binding.syntax = syntax;
    binding.kind = kind;
    binding.resultTypeKey = kind == nativesharp::frontend::MethodCoreOperationKind::Assert ||
            kind == nativesharp::frontend::MethodCoreOperationKind::Assume
        ? "builtin:void" : "builtin:never";
    return binding;
}

AssertionCoreSyntax makeDeepAssertionCoreSyntax(
    std::size_t depth,
    bool panic)
{
    AssertionCoreSyntax fixture;
    fixture.nodes.reserve(depth + 1U);
    fixture.cores.reserve(depth);
    auto* current = appendAssertionCoreSyntax(
        fixture,
        panic ? nativesharp::ast::AstNodeKind::StringLiteralExpression
              : nativesharp::ast::AstNodeKind::BooleanLiteralExpression);
    if (panic)
        current->setText("deep panic");
    else
        current->setTokenKind(nativesharp::lexer::TokenKind::KwTrue);
    for (std::size_t index = 0; index < depth; ++index)
    {
        auto* call = appendAssertionCoreSyntax(
            fixture, nativesharp::ast::AstNodeKind::CallExpression);
        call->addChild(current);
        const auto kind = panic
            ? nativesharp::frontend::MethodCoreOperationKind::Panic
            : index % 2U == 0U
                ? nativesharp::frontend::MethodCoreOperationKind::Assert
                : nativesharp::frontend::MethodCoreOperationKind::Assume;
        fixture.cores.push_back(makeAssertionCoreBinding(call, kind));
        current = call;
    }
    fixture.root = current;
    return fixture;
}

AssertionCoreSyntax makeSingleAssertionCoreSyntax(
    nativesharp::frontend::MethodCoreOperationKind kind,
    std::optional<nativesharp::ast::AstNodeKind> operandKind)
{
    AssertionCoreSyntax fixture;
    fixture.nodes.reserve(2U);
    auto* call = appendAssertionCoreSyntax(
        fixture, nativesharp::ast::AstNodeKind::CallExpression);
    if (operandKind.has_value())
    {
        auto* operand = appendAssertionCoreSyntax(fixture, *operandKind);
        if (*operandKind == nativesharp::ast::AstNodeKind::BooleanLiteralExpression)
            operand->setTokenKind(nativesharp::lexer::TokenKind::KwTrue);
        if (*operandKind == nativesharp::ast::AstNodeKind::StringLiteralExpression)
            operand->setText("panic payload");
        call->addChild(operand);
    }
    fixture.cores.push_back(makeAssertionCoreBinding(call, kind));
    fixture.root = call;
    return fixture;
}

std::unique_ptr<ProjectOopHirNode> lowerAssertionCoreFixture(
    AssertionCoreSyntax& fixture,
    std::string_view expressionTypeKey,
    std::vector<std::size_t> activeCleanupRegions,
    bool addressContext,
    std::string& error)
{
    nativesharp::frontend::MethodExpressionTypeBinding expressionType;
    expressionType.typeKey = std::string(expressionTypeKey);
    ProjectOopHirModel model;
    return nativesharp::frontend::ProjectOopHirModelTestAccess::
        lowerAssertionCoreExpression(
            model,
            fixture.root,
            fixture.nodes,
            fixture.cores,
            expressionType,
            std::move(activeCleanupRegions),
            addressContext,
            error);
}

void testAssertionCoreNominalContracts(TestContext& tests)
{
    using CoreKind = nativesharp::frontend::MethodCoreOperationKind;
    using HirKind = nativesharp::frontend::ProjectOopHirNodeKind;
    std::string error;
    for (const auto [coreKind, hirKind] :
        {std::pair{CoreKind::Assert, HirKind::Assert},
         std::pair{CoreKind::Assume, HirKind::Assume}})
    {
        auto fixture = makeSingleAssertionCoreSyntax(
            coreKind, nativesharp::ast::AstNodeKind::BooleanLiteralExpression);
        auto lowered = lowerAssertionCoreFixture(
            fixture, "builtin:bool", {}, false, error);
        tests.expect(lowered != nullptr && error.empty() && lowered->kind == hirKind &&
                lowered->typeKey == "builtin:void" && lowered->children.size() == 1U &&
                lowered->children.front()->kind == HirKind::BooleanConstant,
            coreKind == CoreKind::Assert
                ? "iterative assert preserves its bool child and void result"
                : "iterative assume preserves its bool child and void result");
        destroyHirTreeIteratively(lowered);
        error.clear();
    }

    auto unreachable = makeSingleAssertionCoreSyntax(CoreKind::Unreachable, std::nullopt);
    auto unreachableNode = lowerAssertionCoreFixture(
        unreachable, "builtin:never", {}, false, error);
    tests.expect(unreachableNode != nullptr && error.empty() &&
            unreachableNode->kind == HirKind::Unreachable &&
            unreachableNode->typeKey == "builtin:never" &&
            unreachableNode->children.empty(),
        "unreachable remains a receiver-free never leaf");
    destroyHirTreeIteratively(unreachableNode);

    error.clear();
    auto emptyPanic = makeSingleAssertionCoreSyntax(CoreKind::Panic, std::nullopt);
    auto emptyPanicNode = lowerAssertionCoreFixture(
        emptyPanic, "builtin:never", {4U, 7U, 9U}, false, error);
    tests.expect(emptyPanicNode != nullptr && error.empty() &&
            emptyPanicNode->kind == HirKind::Panic && emptyPanicNode->children.empty() &&
            emptyPanicNode->cleanupContinuationKind ==
                nativesharp::frontend::MethodCleanupContinuationKind::Exception &&
            emptyPanicNode->cleanupRegionOrdinals ==
                std::vector<std::size_t>{9U, 7U, 4U},
        "payload-free panic preserves its reverse cleanup snapshot");
    destroyHirTreeIteratively(emptyPanicNode);

    error.clear();
    auto literalPanic = makeSingleAssertionCoreSyntax(
        CoreKind::Panic, nativesharp::ast::AstNodeKind::StringLiteralExpression);
    auto literalPanicNode = lowerAssertionCoreFixture(
        literalPanic, "string-literal", {}, false, error);
    tests.expect(literalPanicNode != nullptr && error.empty() &&
            literalPanicNode->kind == HirKind::Panic &&
            literalPanicNode->children.size() == 1U &&
            literalPanicNode->children.front()->kind == HirKind::StringLiteral,
        "iterative panic accepts a string-literal payload exactly once");
    destroyHirTreeIteratively(literalPanicNode);

    error.clear();
    auto stringPanic = makeSingleAssertionCoreSyntax(
        CoreKind::Panic, nativesharp::ast::AstNodeKind::DefaultValueExpression);
    auto stringPanicNode = lowerAssertionCoreFixture(
        stringPanic, "builtin:string", {10U, 20U, 30U}, false, error);
    tests.expect(stringPanicNode != nullptr && error.empty() &&
            stringPanicNode->kind == HirKind::Panic &&
            stringPanicNode->children.size() == 1U &&
            stringPanicNode->children.front()->kind == HirKind::DefaultValue &&
            stringPanicNode->cleanupContinuationKind ==
                nativesharp::frontend::MethodCleanupContinuationKind::Exception &&
            stringPanicNode->cleanupRegionOrdinals ==
                std::vector<std::size_t>{30U, 20U, 10U},
        "panic freezes inner-to-outer cleanup before lowering a builtin:string payload");
    destroyHirTreeIteratively(stringPanicNode);
}

void testAssertionCorePrevalidation(TestContext& tests)
{
    using CoreKind = nativesharp::frontend::MethodCoreOperationKind;
    std::string error;
    auto address = makeSingleAssertionCoreSyntax(
        CoreKind::Assert, nativesharp::ast::AstNodeKind::CallExpression);
    auto addressNode = lowerAssertionCoreFixture(
        address, "builtin:bool", {}, true, error);
    tests.expect(addressNode == nullptr && error == "assert() has no addressable result",
        "assert rejects address context before visiting an invalid child");

    error.clear();
    auto arity = makeSingleAssertionCoreSyntax(
        CoreKind::Assert, nativesharp::ast::AstNodeKind::CallExpression);
    arity.nodes.push_back(std::make_unique<nativesharp::ast::AstNode>(
        nativesharp::ast::AstNodeKind::CallExpression, nativesharp::SourceRange{}));
    arity.nodes.front()->addChild(arity.nodes.back().get());
    auto arityNode = lowerAssertionCoreFixture(
        arity, "builtin:bool", {}, false, error);
    tests.expect(arityNode == nullptr &&
            error == "T07-F06 assertion binding lost its arity/result contract",
        "assert rejects invalid arity before visiting invalid children");

    error.clear();
    auto result = makeSingleAssertionCoreSyntax(
        CoreKind::Panic, nativesharp::ast::AstNodeKind::CallExpression);
    result.cores.front().resultTypeKey = "builtin:void";
    auto resultNode = lowerAssertionCoreFixture(
        result, "builtin:string", {}, false, error);
    tests.expect(resultNode == nullptr &&
            error == "T07-F06 assertion binding lost its arity/result contract",
        "panic rejects an incoherent result type before visiting its invalid payload");
}

void testDeepPanicAssertCallLowering(TestContext& tests)
{
    constexpr std::size_t nestingDepth = 32768U;
    std::string error;
    auto assertions = makeDeepAssertionCoreSyntax(nestingDepth, false);
    auto assertionNode = lowerAssertionCoreFixture(
        assertions, "builtin:bool", {}, false, error);
    tests.expect(assertionNode == nullptr &&
            error == "T07-F06 assertion condition lost its bool type",
        "a 32768-level assert/assume chain reaches its controlled type diagnostic without "
        "process-stack recursion");

    error.clear();
    auto panics = makeDeepAssertionCoreSyntax(nestingDepth, true);
    auto panicNode = lowerAssertionCoreFixture(
        panics, "string-literal", {}, false, error);
    tests.expect(panicNode == nullptr &&
            error == "T07-F06 panic payload lost its string type",
        "a 32768-level panic chain reaches its controlled type diagnostic without "
        "process-stack recursion");

    testAssertionCoreNominalContracts(tests);
    testAssertionCorePrevalidation(tests);
}

struct IteratorCoreCallSyntax final
{
    std::vector<std::unique_ptr<nativesharp::ast::AstNode>> nodes;
    std::vector<nativesharp::frontend::MethodCoreBinding> cores;
    std::vector<nativesharp::frontend::MethodNameBinding> names;
    const nativesharp::ast::AstNode* root = nullptr;
};

nativesharp::ast::AstNode* appendIteratorCoreSyntax(
    IteratorCoreCallSyntax& fixture,
    nativesharp::ast::AstNodeKind kind)
{
    fixture.nodes.push_back(std::make_unique<nativesharp::ast::AstNode>(
        kind, nativesharp::SourceRange{}));
    return fixture.nodes.back().get();
}

nativesharp::frontend::MethodCoreBinding makeIteratorCoreBinding(
    const nativesharp::ast::AstNode* syntax,
    nativesharp::frontend::MethodCoreOperationKind kind)
{
    using CoreKind = nativesharp::frontend::MethodCoreOperationKind;
    nativesharp::frontend::MethodCoreBinding binding;
    binding.syntax = syntax;
    binding.kind = kind;
    binding.resultTypeKey = kind == CoreKind::IteratorGetEnumerator
        ? "type:Deep.Iterator"
        : kind == CoreKind::IteratorMoveNext
            ? "builtin:bool"
            : kind == CoreKind::IteratorMoveNextAsync
                ? "type:Deep.FutureBool"
                : "builtin:void";
    binding.elementTypeKey = "builtin:int";
    return binding;
}

nativesharp::ast::AstNode* appendIteratorLocal(IteratorCoreCallSyntax& fixture)
{
    auto* local = appendIteratorCoreSyntax(
        fixture, nativesharp::ast::AstNodeKind::IdentifierExpression);
    fixture.names.emplace_back();
    auto& binding = fixture.names.back();
    binding.kind = nativesharp::frontend::MethodNameBindingKind::Local;
    binding.syntax = local;
    binding.name = "iterator";
    binding.typeKey = "type:Deep.Iterator";
    binding.localOrdinal = 0U;
    return local;
}

nativesharp::ast::AstNode* appendIteratorCoreLayer(
    IteratorCoreCallSyntax& fixture,
    nativesharp::ast::AstNode* receiver,
    nativesharp::frontend::MethodCoreOperationKind kind)
{
    auto* member = appendIteratorCoreSyntax(
        fixture, nativesharp::ast::AstNodeKind::MemberExpression);
    member->setFirst(receiver);
    auto* call = appendIteratorCoreSyntax(
        fixture, nativesharp::ast::AstNodeKind::CallExpression);
    call->setFirst(member);
    fixture.cores.push_back(makeIteratorCoreBinding(call, kind));
    return call;
}

IteratorCoreCallSyntax makeDeepIteratorCoreCallSyntax(
    std::size_t depth,
    nativesharp::frontend::MethodCoreOperationKind kind)
{
    IteratorCoreCallSyntax fixture;
    fixture.nodes.reserve(depth * 2U + 1U);
    fixture.cores.reserve(depth);
    fixture.names.reserve(1U);
    auto* current = appendIteratorLocal(fixture);
    for (std::size_t index = 0; index < depth; ++index)
        current = appendIteratorCoreLayer(fixture, current, kind);
    fixture.root = current;
    return fixture;
}

std::unique_ptr<ProjectOopHirNode> lowerIteratorCoreCallFixture(
    IteratorCoreCallSyntax& fixture,
    std::optional<std::size_t> exceptionHandlerOrdinal,
    bool addressContext,
    std::string& error)
{
    nativesharp::frontend::MethodExpressionTypeBinding expressionType;
    expressionType.typeKey = "type:Deep.Iterator";
    nativesharp::frontend::ProjectMethodBodyModel methodBodyModel;
    ProjectOopHirModel model;
    return nativesharp::frontend::ProjectOopHirModelTestAccess::
        lowerIteratorCoreCallExpression(
            model,
            methodBodyModel,
            fixture.root,
            fixture.nodes,
            fixture.cores,
            fixture.names,
            expressionType,
            exceptionHandlerOrdinal,
            addressContext,
            error);
}

bool deepIteratorGetEnumeratorMatches(
    const ProjectOopHirNode* node,
    std::size_t expectedDepth)
{
    using HirKind = nativesharp::frontend::ProjectOopHirNodeKind;
    std::size_t observedDepth = 0U;
    while (node != nullptr && node->kind == HirKind::IteratorGetEnumerator)
    {
        if (node->typeKey != "type:Deep.Iterator" ||
            node->elementTypeKey != "builtin:int" || node->children.size() != 1U ||
            node->argumentCount != 0U || !node->argumentTypeKeys.empty())
        {
            return false;
        }
        ++observedDepth;
        node = node->children.front().get();
    }
    return observedDepth == expectedDepth && node != nullptr &&
        node->kind == HirKind::LocalValue && node->localOrdinal == 0U;
}

nativesharp::frontend::ProjectOopHirNodeKind iteratorHirKind(
    nativesharp::frontend::MethodCoreOperationKind kind)
{
    using CoreKind = nativesharp::frontend::MethodCoreOperationKind;
    using HirKind = nativesharp::frontend::ProjectOopHirNodeKind;
    if (kind == CoreKind::IteratorMoveNext) return HirKind::IteratorMoveNext;
    if (kind == CoreKind::IteratorGetEnumerator) return HirKind::IteratorGetEnumerator;
    if (kind == CoreKind::IteratorDrop) return HirKind::IteratorDrop;
    if (kind == CoreKind::IteratorMoveNextAsync) return HirKind::IteratorMoveNextAsync;
    return HirKind::IteratorCancel;
}

void testIteratorCoreCallContracts(TestContext& tests)
{
    using CoreKind = nativesharp::frontend::MethodCoreOperationKind;
    using HirKind = nativesharp::frontend::ProjectOopHirNodeKind;
    const std::array<CoreKind, 5U> kinds{
        CoreKind::IteratorMoveNext,
        CoreKind::IteratorGetEnumerator,
        CoreKind::IteratorDrop,
        CoreKind::IteratorMoveNextAsync,
        CoreKind::IteratorCancel,
    };
    std::string error;
    for (const CoreKind kind : kinds)
    {
        auto fixture = makeDeepIteratorCoreCallSyntax(1U, kind);
        const auto expectedBinding = fixture.cores.front();
        auto lowered = lowerIteratorCoreCallFixture(fixture, 77U, false, error);
        const bool valueReceiver = kind == CoreKind::IteratorGetEnumerator;
        const std::string observed = lowered == nullptr
            ? "null; error=" + error
            : std::string(nativesharp::frontend::projectOopHirNodeKindName(lowered->kind)) +
                "; child=" + (lowered->children.empty()
                    ? "none"
                    : nativesharp::frontend::projectOopHirNodeKindName(
                        lowered->children.front()->kind)) +
                "; handler=" + (lowered->exceptionTargetRegionOrdinal.has_value()
                    ? std::to_string(*lowered->exceptionTargetRegionOrdinal) : "none");
        tests.expect(lowered != nullptr && error.empty() &&
                lowered->kind == iteratorHirKind(kind) &&
                lowered->typeKey == expectedBinding.resultTypeKey &&
                lowered->elementTypeKey == expectedBinding.elementTypeKey &&
                lowered->children.size() == 1U &&
                lowered->children.front()->kind ==
                    (valueReceiver ? HirKind::LocalValue : HirKind::LocalAddress) &&
                lowered->exceptionTargetRegionOrdinal == 77U &&
                lowered->argumentCount == 0U && lowered->argumentTypeKeys.empty(),
            std::string(nativesharp::frontend::methodCoreOperationKindName(kind)) +
                " preserves receiver context, specialized kind, metadata, and exception target (" +
                observed + ")");
        destroyHirTreeIteratively(lowered);
        error.clear();
    }

    auto withoutHandler = makeDeepIteratorCoreCallSyntax(
        1U, CoreKind::IteratorGetEnumerator);
    auto noHandlerNode = lowerIteratorCoreCallFixture(
        withoutHandler, std::nullopt, false, error);
    tests.expect(noHandlerNode != nullptr && error.empty() &&
            !noHandlerNode->exceptionTargetRegionOrdinal.has_value(),
        "iterator core call leaves exception target absent without an active handler");
    destroyHirTreeIteratively(noHandlerNode);
}

void testIteratorCoreCallInvalidShapes(TestContext& tests)
{
    using AstKind = nativesharp::ast::AstNodeKind;
    using CoreKind = nativesharp::frontend::MethodCoreOperationKind;
    std::string error;

    auto address = makeDeepIteratorCoreCallSyntax(1U, CoreKind::IteratorGetEnumerator);
    auto* invalidReceiver = appendIteratorCoreSyntax(address, AstKind::CallExpression);
    address.nodes[1]->setFirst(invalidReceiver);
    auto addressNode = lowerIteratorCoreCallFixture(address, std::nullopt, true, error);
    tests.expect(addressNode == nullptr &&
            error == "iterator-get-enumerator() has an invalid call shape",
        "iterator get-enumerator rejects address context before lowering its sentinel receiver");

    error.clear();
    auto argument = makeDeepIteratorCoreCallSyntax(1U, CoreKind::IteratorMoveNext);
    auto* invalidArgument = appendIteratorCoreSyntax(argument, AstKind::CallExpression);
    argument.nodes[2]->addChild(invalidArgument);
    auto argumentNode = lowerIteratorCoreCallFixture(argument, std::nullopt, false, error);
    tests.expect(argumentNode == nullptr &&
            error == "iterator-move-next() has an invalid call shape",
        "iterator move-next rejects explicit arguments before lowering its receiver");

    error.clear();
    IteratorCoreCallSyntax missingFirst;
    auto* missingCall = appendIteratorCoreSyntax(missingFirst, AstKind::CallExpression);
    missingFirst.cores.push_back(makeIteratorCoreBinding(missingCall, CoreKind::IteratorDrop));
    missingFirst.root = missingCall;
    auto missingFirstNode = lowerIteratorCoreCallFixture(
        missingFirst, std::nullopt, false, error);
    tests.expect(missingFirstNode == nullptr &&
            error == "iterator-drop() has an invalid call shape",
        "iterator drop preserves the exact missing-member diagnostic");

    error.clear();
    IteratorCoreCallSyntax missingReceiver;
    auto* emptyMember = appendIteratorCoreSyntax(missingReceiver, AstKind::MemberExpression);
    auto* missingReceiverCall = appendIteratorCoreSyntax(
        missingReceiver, AstKind::CallExpression);
    missingReceiverCall->setFirst(emptyMember);
    missingReceiver.cores.push_back(makeIteratorCoreBinding(
        missingReceiverCall, CoreKind::IteratorMoveNextAsync));
    missingReceiver.root = missingReceiverCall;
    auto missingReceiverNode = lowerIteratorCoreCallFixture(
        missingReceiver, std::nullopt, false, error);
    tests.expect(missingReceiverNode == nullptr &&
            error == "iterator-move-next-async() has an invalid call shape",
        "iterator move-next-async preserves the exact missing-receiver diagnostic");

    error.clear();
    auto mutating = makeDeepIteratorCoreCallSyntax(32768U, CoreKind::IteratorCancel);
    auto mutatingNode = lowerIteratorCoreCallFixture(
        mutating, std::nullopt, false, error);
    tests.expect(mutatingNode == nullptr &&
            error == "iterator-cancel() has an invalid call shape",
        "a deep mutating iterator chain reaches its controlled address-shape diagnostic (" +
            error + ")");
}

void testDeepIteratorCoreCallLowering(TestContext& tests)
{
    constexpr std::size_t nestingDepth = 32768U;
    using CoreKind = nativesharp::frontend::MethodCoreOperationKind;
    std::string error;
    auto fixture = makeDeepIteratorCoreCallSyntax(
        nestingDepth, CoreKind::IteratorGetEnumerator);
    auto lowered = lowerIteratorCoreCallFixture(
        fixture, std::nullopt, false, error);
    tests.expect(lowered != nullptr && error.empty(),
        "a 32768-level iterator get-enumerator chain lowers without process-stack recursion (" +
            error + ")");
    tests.expect(deepIteratorGetEnumeratorMatches(lowered.get(), nestingDepth),
        "iterator core frames preserve every specialized node, type, element type, and value edge");
    destroyHirTreeIteratively(lowered);

    testIteratorCoreCallContracts(tests);
    testIteratorCoreCallInvalidShapes(tests);
}

struct CoreOperandCallSyntax final
{
    std::vector<std::unique_ptr<nativesharp::ast::AstNode>> nodes;
    std::vector<nativesharp::frontend::MethodCoreBinding> cores;
    std::vector<nativesharp::frontend::MethodCallBinding> calls;
    std::vector<nativesharp::frontend::MethodNameBinding> names;
    const nativesharp::ast::AstNode* root = nullptr;
};

nativesharp::ast::AstNode* appendCoreOperandSyntax(
    CoreOperandCallSyntax& fixture,
    nativesharp::ast::AstNodeKind kind)
{
    fixture.nodes.push_back(std::make_unique<nativesharp::ast::AstNode>(
        kind, nativesharp::SourceRange{}));
    return fixture.nodes.back().get();
}

nativesharp::ast::AstNode* appendCoreOperandString(CoreOperandCallSyntax& fixture)
{
    auto* literal = appendCoreOperandSyntax(
        fixture, nativesharp::ast::AstNodeKind::StringLiteralExpression);
    literal->setText("operand");
    return literal;
}

nativesharp::ast::AstNode* appendCoreOperandInteger(
    CoreOperandCallSyntax& fixture,
    std::uint64_t value)
{
    auto* literal = appendCoreOperandSyntax(
        fixture, nativesharp::ast::AstNodeKind::IntegerLiteralExpression);
    literal->setIntegerValue(value);
    return literal;
}

nativesharp::ast::AstNode* appendCoreOperandLocal(
    CoreOperandCallSyntax& fixture,
    std::string typeKey)
{
    auto* local = appendCoreOperandSyntax(
        fixture, nativesharp::ast::AstNodeKind::IdentifierExpression);
    fixture.names.emplace_back();
    auto& name = fixture.names.back();
    name.kind = nativesharp::frontend::MethodNameBindingKind::Local;
    name.syntax = local;
    name.name = "source";
    name.typeKey = std::move(typeKey);
    name.localOrdinal = 0U;
    return local;
}

void appendCoreOperandBindings(
    CoreOperandCallSyntax& fixture,
    nativesharp::ast::AstNode* call,
    nativesharp::frontend::MethodCoreOperationKind kind,
    std::string resultTypeKey = "builtin:string")
{
    fixture.cores.emplace_back();
    auto& core = fixture.cores.back();
    core.syntax = call;
    core.kind = kind;
    core.resultTypeKey = std::move(resultTypeKey);
    fixture.calls.emplace_back();
    auto& binding = fixture.calls.back();
    binding.syntax = call;
    binding.resolution = nativesharp::frontend::MethodCallResolutionKind::Resolved;
    binding.staticCall = true;
    binding.selectedMemberOrdinal = 0U;
    binding.resultTypeKey = core.resultTypeKey;
}

CoreOperandCallSyntax makeCoreOperandTableSyntax(
    nativesharp::frontend::MethodCoreOperationKind kind,
    std::size_t operandCount,
    bool sentinelOperands = false)
{
    CoreOperandCallSyntax fixture;
    fixture.nodes.reserve(operandCount + 1U);
    fixture.cores.reserve(1U);
    fixture.calls.reserve(1U);
    auto* call = appendCoreOperandSyntax(
        fixture, nativesharp::ast::AstNodeKind::CallExpression);
    for (std::size_t index = 0; index < operandCount; ++index)
    {
        auto* operand = sentinelOperands
            ? appendCoreOperandSyntax(fixture, nativesharp::ast::AstNodeKind::CallExpression)
            : appendCoreOperandString(fixture);
        call->addChild(operand);
    }
    appendCoreOperandBindings(fixture, call, kind);
    fixture.root = call;
    return fixture;
}

CoreOperandCallSyntax makeDeepStringConcatSyntax(std::size_t depth)
{
    using CoreKind = nativesharp::frontend::MethodCoreOperationKind;
    CoreOperandCallSyntax fixture;
    fixture.nodes.reserve(depth * 2U + 1U);
    fixture.cores.reserve(depth);
    fixture.calls.reserve(depth);
    auto* current = appendCoreOperandString(fixture);
    for (std::size_t index = 0; index < depth; ++index)
    {
        auto* right = appendCoreOperandString(fixture);
        auto* call = appendCoreOperandSyntax(
            fixture, nativesharp::ast::AstNodeKind::CallExpression);
        call->addChild(current);
        call->addChild(right);
        appendCoreOperandBindings(fixture, call, CoreKind::StringConcat);
        current = call;
    }
    fixture.root = current;
    return fixture;
}

CoreOperandCallSyntax makeViewCoreOperandSyntax(
    nativesharp::frontend::MethodCoreOperationKind kind)
{
    CoreOperandCallSyntax fixture;
    fixture.nodes.reserve(5U);
    fixture.cores.reserve(1U);
    fixture.names.reserve(1U);
    auto* receiver = appendCoreOperandLocal(fixture, "type:Source");
    auto* member = appendCoreOperandSyntax(
        fixture, nativesharp::ast::AstNodeKind::MemberExpression);
    member->setFirst(receiver);
    auto* call = appendCoreOperandSyntax(
        fixture, nativesharp::ast::AstNodeKind::CallExpression);
    call->setFirst(member);
    call->addChild(appendCoreOperandInteger(fixture, 3U));
    call->addChild(appendCoreOperandInteger(fixture, 7U));
    fixture.cores.emplace_back();
    auto& core = fixture.cores.back();
    core.syntax = call;
    core.kind = kind;
    core.resultTypeKey = "type:View";
    core.elementTypeKey = "builtin:char";
    fixture.root = call;
    return fixture;
}

std::unique_ptr<ProjectOopHirNode> lowerCoreOperandCallFixture(
    CoreOperandCallSyntax& fixture,
    bool addressContext,
    std::string& error,
    const nativesharp::frontend::ProjectNameLookup* nameLookup = nullptr,
    const nativesharp::frontend::ProjectMemberModel* memberModel = nullptr,
    const std::vector<nativesharp::frontend::MethodBorrowBinding>* borrows = nullptr)
{
    nativesharp::frontend::MethodExpressionTypeBinding expressionType;
    expressionType.typeKey = "builtin:string";
    nativesharp::frontend::ProjectMethodBodyModel methodBodyModel;
    ProjectOopHirModel model;
    return nativesharp::frontend::ProjectOopHirModelTestAccess::
        lowerCoreOperandCallExpression(
            model,
            methodBodyModel,
            fixture.root,
            fixture.nodes,
            fixture.cores,
            fixture.calls,
            fixture.names,
            expressionType,
            addressContext,
            error,
            nameLookup,
            memberModel,
            borrows);
}

bool deepStringConcatMatches(const ProjectOopHirNode* node, std::size_t expectedDepth)
{
    using HirKind = nativesharp::frontend::ProjectOopHirNodeKind;
    std::size_t observedDepth = 0U;
    while (node != nullptr && node->kind == HirKind::StringConcat)
    {
        if (node->typeKey != "builtin:string" || node->children.size() != 2U ||
            node->children[1]->kind != HirKind::StringLiteral)
            return false;
        ++observedDepth;
        node = node->children.front().get();
    }
    return observedDepth == expectedDepth && node != nullptr &&
        node->kind == HirKind::StringLiteral;
}

void testCoreOperandConversions(TestContext& tests)
{
    using CoreKind = nativesharp::frontend::MethodCoreOperationKind;
    using ConversionKind = nativesharp::frontend::ProjectConversionKind;
    using HirKind = nativesharp::frontend::ProjectOopHirNodeKind;
    std::string error;
    auto fixture = makeCoreOperandTableSyntax(CoreKind::StringSubstring, 2U);
    auto* receiver = appendCoreOperandLocal(fixture, "builtin:string");
    fixture.calls.front().forwardedReceiver = true;
    fixture.calls.front().receiverSyntax = receiver;
    nativesharp::frontend::ProjectImplicitConversion numeric;
    numeric.kind = ConversionKind::Numeric;
    numeric.sourceTypeKey = "builtin:string";
    numeric.targetTypeKey = "builtin:string";
    nativesharp::frontend::ProjectImplicitConversion identity;
    identity.kind = ConversionKind::Identity;
    identity.sourceTypeKey = "builtin:string";
    identity.targetTypeKey = "builtin:string";
    fixture.calls.front().selectedConversions = {numeric, identity, numeric};
    auto lowered = lowerCoreOperandCallFixture(fixture, false, error);
    tests.expect(lowered != nullptr && error.empty() &&
            lowered->kind == HirKind::StringSubstring && lowered->children.size() == 3U &&
            lowered->children[0]->kind == HirKind::Conversion &&
            lowered->children[0]->children.front()->kind == HirKind::LocalValue &&
            lowered->children[1]->kind == HirKind::StringLiteral &&
            lowered->children[2]->kind == HirKind::Conversion,
        "forwarded core receiver owns conversion index zero and arguments keep source order");
    destroyHirTreeIteratively(lowered);

    error.clear();
    auto shortVector = makeCoreOperandTableSyntax(CoreKind::StringConcat, 2U);
    shortVector.calls.front().selectedConversions = {numeric};
    auto shortLowered = lowerCoreOperandCallFixture(shortVector, false, error);
    tests.expect(shortLowered != nullptr && error.empty() &&
            shortLowered->children.size() == 2U &&
            shortLowered->children[0]->kind == HirKind::Conversion &&
            shortLowered->children[1]->kind == HirKind::StringLiteral,
        "a short selected-conversion vector leaves missing operand entries as identity");
    destroyHirTreeIteratively(shortLowered);
}

void testViewCoreOperandContracts(TestContext& tests)
{
    using CoreKind = nativesharp::frontend::MethodCoreOperationKind;
    using HirKind = nativesharp::frontend::ProjectOopHirNodeKind;
    struct ViewExpectation final
    {
        CoreKind coreKind;
        HirKind hirKind;
        bool receiverAddress;
    };
    const std::array<ViewExpectation, 5U> expectations{{
        {CoreKind::StringViewFromString, HirKind::StringViewFromString, false},
        {CoreKind::SpanFromArray, HirKind::SpanFromArray, false},
        {CoreKind::ReadOnlySpanFromArray, HirKind::ReadOnlySpanFromArray, false},
        {CoreKind::SpanFromFixedArray, HirKind::SpanFromFixedArray, true},
        {CoreKind::ReadOnlySpanFromFixedArray, HirKind::ReadOnlySpanFromFixedArray, true},
    }};
    std::string error;
    for (const ViewExpectation& expectation : expectations)
    {
        auto fixture = makeViewCoreOperandSyntax(expectation.coreKind);
        auto lowered = lowerCoreOperandCallFixture(fixture, false, error);
        tests.expect(lowered != nullptr && error.empty() &&
                lowered->kind == expectation.hirKind && lowered->typeKey == "type:View" &&
                lowered->elementTypeKey == "builtin:char" && lowered->children.size() == 3U &&
                lowered->children[0]->kind == (expectation.receiverAddress
                    ? HirKind::LocalAddress : HirKind::LocalValue) &&
                lowered->children[1]->kind == HirKind::IntegerConstant &&
                lowered->children[1]->integerValue == 3U &&
                lowered->children[2]->kind == HirKind::IntegerConstant &&
                lowered->children[2]->integerValue == 7U,
            std::string(nativesharp::frontend::methodCoreOperationKindName(
                expectation.coreKind)) + " preserves receiver context, order, and view metadata");
        destroyHirTreeIteratively(lowered);
        error.clear();
    }

    auto stringViewAddress = makeViewCoreOperandSyntax(CoreKind::StringViewFromString);
    auto stringViewNode = lowerCoreOperandCallFixture(stringViewAddress, true, error);
    tests.expect(stringViewNode == nullptr &&
            error == "a StringView rest capture is a value and is not addressable",
        "StringView rejects address context with its historical diagnostic");
    error.clear();
    auto spanAddress = makeViewCoreOperandSyntax(CoreKind::SpanFromFixedArray);
    auto spanNode = lowerCoreOperandCallFixture(spanAddress, true, error);
    tests.expect(spanNode == nullptr &&
            error == "a Span/ReadOnlySpan rest capture is a value and is not addressable",
        "Span rejects address context with its historical diagnostic");
}

void testCoreOperandPrevalidation(TestContext& tests)
{
    using CoreKind = nativesharp::frontend::MethodCoreOperationKind;
    std::string error;
    auto address = makeCoreOperandTableSyntax(CoreKind::StringConcat, 2U, true);
    auto addressNode = lowerCoreOperandCallFixture(address, true, error);
    tests.expect(addressNode == nullptr &&
            error == "Stage 51 NativeSharp.Core.String result is not addressable",
        "table core rejects address context before visiting sentinel operands");

    error.clear();
    auto missingCall = makeCoreOperandTableSyntax(CoreKind::StringConcat, 2U, true);
    missingCall.calls.clear();
    auto missingCallNode = lowerCoreOperandCallFixture(missingCall, false, error);
    tests.expect(missingCallNode == nullptr &&
            error == "Stage 51 string intrinsic requires a resolved Core.String call",
        "table core rejects a missing call binding before visiting sentinel operands");

    error.clear();
    auto missingOrdinal = makeCoreOperandTableSyntax(CoreKind::StringConcat, 2U, true);
    missingOrdinal.calls.front().selectedMemberOrdinal.reset();
    auto missingOrdinalNode = lowerCoreOperandCallFixture(missingOrdinal, false, error);
    tests.expect(missingOrdinalNode == nullptr &&
            error == "Stage 51 string intrinsic requires a resolved Core.String call",
        "table core rejects a missing selected ordinal before visiting sentinel operands");

    error.clear();
    auto missingReceiver = makeCoreOperandTableSyntax(CoreKind::StringSubstring, 2U, true);
    missingReceiver.calls.front().forwardedReceiver = true;
    auto missingReceiverNode = lowerCoreOperandCallFixture(missingReceiver, false, error);
    tests.expect(missingReceiverNode == nullptr &&
            error == "Stage 51 forwarded string call has no receiver",
        "table core rejects a null forwarded receiver before visiting sentinel operands");

    error.clear();
    auto wrongArity = makeCoreOperandTableSyntax(CoreKind::StringConcat, 1U, true);
    auto wrongArityNode = lowerCoreOperandCallFixture(wrongArity, false, error);
    tests.expect(wrongArityNode == nullptr &&
            error == "Stage 51 string intrinsic received an invalid operand count",
        "table core rejects wrong arity before visiting sentinel operands");
}

