        move->setFirst(moveSource);
        auto* moveSpread = addMove(AstKind::SpreadElementExpression);
        moveSpread->setFirst(move);
        auto* moveRoot = addMove(AstKind::AggregateInitializerExpression);
        moveRoot->addChild(moveSpread);
