    std::vector<nativesharp::frontend::ProjectOopMirStructLayout> layouts(3U);
    layouts[0].typeKey = "test:unrelated";
    layouts[0].size = 41U;
    layouts[1].typeKey = "test:awaited";
    layouts[1].size = 3U;
    layouts[2].typeKey = "test:awaited";
